library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity rom_data is
  port (
    address : in  std_logic_vector(13 downto 0);
    clock   : in  std_logic := '1';
    q       : out std_logic_vector(15 downto 0)
  );
end rom_data;

architecture rtl of rom_data is
  type rom_array_t is array (0 to 16383) of signed(15 downto 0);

  constant MEM : rom_array_t := (
    0      => to_signed(0, 16),
    1      => to_signed(2, 16),
    2      => to_signed(-12, 16),
    3      => to_signed(-12, 16),
    4      => to_signed(2, 16),
    5      => to_signed(22, 16),
    6      => to_signed(22, 16),
    7      => to_signed(22, 16),
    16380  => to_signed(-782, 16),
    16381  => to_signed(-1062, 16),
    16382  => to_signed(-782, 16),
    16383  => to_signed(-592, 16),
    others => to_signed(0, 16)
  );
begin
  process (clock)
  begin
    if rising_edge(clock) then
      q <= std_logic_vector(MEM(to_integer(unsigned(address))));
    end if;
  end process;
end rtl;

